import { SqlClient } from "effect/sql";
// `attach` (decision 0153, docs/features/todos.md#leaves): a person sets the issue of a TODO whose issue is none, or a
// deleted one. `stack_ops` takes the op, its outcome `issue_set` and its refusals `issue_not_found` and `attached`.
//
// Each ALTER takes the table's ACCESS EXCLUSIVE lock, on a table every stack op reads and writes: a deploy that can't get
// it soon fails and is run again. Each CHECK is added NOT VALID, so neither scans the table under that lock, and new and
// changed rows are checked at once. Every existing row is within the wider lists. The migrator runs pending migrations in
// one transaction, so validating here would scan under the same lock: `ops/stack-ops/validate.ts` validates them after
// the deploy, under a lock that lets stack ops run.
//
